groups=[('Firebase / A4','integration-results.json',7),('Browser / A4','ui-results.json',8),('Firebase / BOQ เดิม','regression/baseline-integration-results.json',6),('Browser / BOQ เดิม','regression/baseline-ui-results.json',13),('Firebase / BS เดิม','regression/bs-integration-results.json',7),('Browser / BS เดิม','regression/bs-ui-results.json',8)]
for _,name,count in groups:
    data=load(name);assert len(data['results'])==count and all(r['status']=='PASS' for r in data['results'])
build=load('build-browser-results.json');assert build['status']=='PASS' and build['actualBuiltA4Download']
pdf=load('pdf-verification.json');assert len(pdf['results'])==6 and all(r['status']=='PASS' for r in pdf['results'])
checkpoint=root/'output/emulator-checkpoints/v0.7-verified-20261011';metadata=json.loads((checkpoint/'firebase-export-metadata.json').read_text())
for name in ['auth','firestore','storage']:assert (checkpoint/metadata[name]['path']).is_dir()
assert (checkpoint/metadata['firestore']['metadata_file']).is_file()
deliverables=[]
for src,dest in [('frozen-member-A4.pdf','BS8666-2000-A4-member-draft.pdf'),('frozen-package-A4.pdf','BS8666-2000-A4-package-draft.pdf')]:
    path=root/'output/pdf'/dest;sha=hashlib.sha256(path.read_bytes()).hexdigest();assert sha==hashlib.sha256((out/'downloads'/src).read_bytes()).hexdigest();deliverables.append({'file':dest,'sha256':sha})
summary={'softwareScenariosPassed':83,'unit':33,'firebase':20,'browser':29,'builtApp':1,'pdfs':6,'a4Leaves':sum(r['pages'] for r in pdf['results']),'initialJavaScriptBytes':build['totalInitialJavaScriptBytes'],'checkpoint':'v0.7-verified-20261011','checkpointExportVerified':True,'checkpointReimportTested':False,'engineeringAccepted':False,'cloudDeployed':False,'deliverables':deliverables}
(out/'verification-summary.json').write_text(json.dumps(summary,indent=2),encoding='utf-8')
testrows=''.join(f'<tr><td>{escape(label)}</td><td>{count}</td><td class="pass">PASS</td><td><a href="{name}">ผลทดสอบ</a></td></tr>' for label,name,count in groups)
pdfrows=''.join(f'<tr><td><a href="downloads/{r["file"]}">{r["file"]}</a></td><td>{r["pages"]}</td><td>{escape(" / ".join(r["scheduleReferences"]))}</td><td>A4 · PASS</td></tr>' for r in pdf['results'])
